var K = ["workers","incidents","toolbox","training","substances","rams","subbies","subdocs","insurance","vehicles","checks","crashes","assets","services","requests","leave","vservices","taskstat","hazards","increports","materials","stockmoves","ptmsheets","claims","covertasks","companycerts","subjobs","cphsp","prestarts","hspolicy","notifyrules","suppliers","pos","signatures","signons","notices","scaffinsp","tbtopics","ramstypes","cphspwording"];
var q = ($('Data Hook').first().json.query || {});
var want = String(q.t || '').split(',').map(function(s){ return s.trim(); }).filter(Boolean);
var out = {};
K.forEach(function(k){ out[k] = $('Get ' + k).all().map(function(i){ return i.json; }).filter(function(r){ return r && r.id; }); });
out.signons = out.signons.map(function(r){ var o = Object.assign({}, r); o.has_signature = r.signature ? 'Yes' : 'No'; delete o.signature; return o; });
out.hsmeet = out.toolbox;
/* Signatures live on each person's Team record (cbs_workers.signature, 27/10/2026). The signatures list every page reads
   (approvals in the hub, RAMS and CPHSP builders) is built from Team: current staff with a saved signature. When workers
   were not loaded (t= without workers), they are read once here. cbs_signatures is kept only as a backup. */
var W = out.workers;
if ((!W || !W.length) && want.length && want.indexOf('signatures') > -1) {
  try { W = await this.helpers.httpRequest({ method: 'POST', url: 'https://old-hub.example/webhook/cbs-admin-save?a=list&t=workers', body: {}, json: true, timeout: 20000 }); } catch (e) { W = []; }
  W = (Array.isArray(W) ? W : []).filter(function(r){ return r && r.id; });
}
out.signatures = (W || []).filter(function(w){ return w && String(w.name || '').trim() && w.signature && w.active !== false; })
  .map(function(w){ return { id: w.id, worker_id: w.id, name: String(w.name).trim(), role: w.role || '', image: w.signature, notes: '' }; });
/* Each person keeps their signature when the request also asks for signatures (the hub's own load, which shows and edits it on the
   Team record). Other pages that only ask for workers get it dropped to stay light (has_signature tells them whether one exists). */
if (want.length && want.indexOf('signatures') < 0) { out.workers = out.workers.map(function(r){ var o = Object.assign({}, r); o.has_signature = r.signature ? true : false; delete o.signature; return o; }); }
if (want.length) { var o2 = {}; want.forEach(function(t){ if (out[t]) o2[t] = out[t]; }); out = o2; }
return [{ json: out }];

